import React, { useMemo, useState } from 'react';
import { Typography, Table, TableBody, TableCell, TableContainer, TableHead, TableRow, Paper, TextField, Stack, Chip, MenuItem, Pagination, Box } from '@mui/material';

const initialTests = [
  { test_name: 'Login Flow', module_name: 'Auth', flaky_score: 83, executions: 120, failures: 18, risk_level: 'Critical', recommendation: 'Stabilize auth dependency timing.' },
  { test_name: 'Checkout API', module_name: 'Payments', flaky_score: 76, executions: 98, failures: 14, risk_level: 'High', recommendation: 'Add retry jitter and timeouts.' },
  { test_name: 'Search Filter', module_name: 'Search', flaky_score: 61, executions: 112, failures: 9, risk_level: 'Medium', recommendation: 'Investigate async rendering.' },
  { test_name: 'Billing Sync', module_name: 'Billing', flaky_score: 41, executions: 84, failures: 4, risk_level: 'Low', recommendation: 'Add resilience logging.' },
];

function FlakyTestsPage() {
  const [query, setQuery] = useState('');
  const [riskFilter, setRiskFilter] = useState('All');
  const [page, setPage] = useState(1);
  const pageSize = 2;

  const filteredTests = useMemo(() => {
    return initialTests.filter((row) => {
      const matchesQuery = `${row.test_name} ${row.module_name}`.toLowerCase().includes(query.toLowerCase());
      const matchesRisk = riskFilter === 'All' || row.risk_level === riskFilter;
      return matchesQuery && matchesRisk;
    });
  }, [query, riskFilter]);

  const pagedTests = filteredTests.slice((page - 1) * pageSize, page * pageSize);

  return (
    <Box>
      <Typography variant="h4" gutterBottom>Flaky Tests Observatory</Typography>
      <Stack direction={{ xs: 'column', md: 'row' }} spacing={2} mb={2}>
        <TextField size="small" label="Search tests" value={query} onChange={(e) => { setQuery(e.target.value); setPage(1); }} fullWidth />
        <TextField select size="small" label="Risk Level" value={riskFilter} onChange={(e) => { setRiskFilter(e.target.value); setPage(1); }} sx={{ minWidth: 180 }}>
          <MenuItem value="All">All</MenuItem>
          <MenuItem value="Critical">Critical</MenuItem>
          <MenuItem value="High">High</MenuItem>
          <MenuItem value="Medium">Medium</MenuItem>
          <MenuItem value="Low">Low</MenuItem>
        </TextField>
      </Stack>
      <TableContainer component={Paper}>
        <Table>
          <TableHead>
            <TableRow>
              <TableCell>Test Name</TableCell>
              <TableCell>Module</TableCell>
              <TableCell>Flaky Score</TableCell>
              <TableCell>Executions</TableCell>
              <TableCell>Failures</TableCell>
              <TableCell>Risk Level</TableCell>
              <TableCell>Recommendation</TableCell>
            </TableRow>
          </TableHead>
          <TableBody>
            {pagedTests.map((row) => (
              <TableRow key={`${row.test_name}-${row.module_name}`}>
                <TableCell>{row.test_name}</TableCell>
                <TableCell>{row.module_name}</TableCell>
                <TableCell>{row.flaky_score}%</TableCell>
                <TableCell>{row.executions}</TableCell>
                <TableCell>{row.failures}</TableCell>
                <TableCell><Chip label={row.risk_level} color={row.risk_level === 'Critical' ? 'error' : row.risk_level === 'High' ? 'warning' : row.risk_level === 'Medium' ? 'info' : 'success'} size="small" /></TableCell>
                <TableCell>{row.recommendation}</TableCell>
              </TableRow>
            ))}
          </TableBody>
        </Table>
      </TableContainer>
      <Box mt={2} display="flex" justifyContent="flex-end">
        <Pagination count={Math.max(1, Math.ceil(filteredTests.length / pageSize))} page={page - 1} onChange={(_, value) => setPage(value)} color="primary" />
      </Box>
    </Box>
  );
}

export default FlakyTestsPage;
